import { memo, useCallback, useMemo, useState } from "react";

export function ExerciseSearch({ exercises }) {
  const [query, setQuery] = useState("");
  const [notes, setNotes] = useState("");
  const [selectedId, setSelectedId] = useState(null);

  // Measured: 60 ms. Recomputes only when exercises or query change, not on notes typing.
  const results = useMemo(() => rankExercises(exercises, query), [exercises, query]);

  const select = useCallback((id) => setSelectedId(id), []);   // stable for memo(Row).

  return (
    <>
      <input aria-label="Search exercises" value={query} onChange={(e) => setQuery(e.target.value)} />
      <textarea aria-label="Notes" value={notes} onChange={(e) => setNotes(e.target.value)} />
      <ul>{results.slice(0, 50).map((ex) => <Row key={ex.id} ex={ex} onSelect={select} />)}</ul>
    </>
  );
}

const Row = memo(function Row({ ex, onSelect }) {
  return <li><button type="button" onClick={() => onSelect(ex.id)}>{ex.title}</button></li>;
});
```

| Tool | Caches | Worth it when |
|---|---|---|
| useMemo. | a computed value. | the computation is measurably slow. |
| useCallback. | a function identity. | it's passed to a memo child or an effect dependency. |
| memo. | a component's render. | it renders slowly and gets stable props. |

